export function AirlineFooter() {
  const { t } = useI18n();
  const year = new Date().getFullYear();
  const whatsappNumber = process.env.NEXT_PUBLIC_WHATSAPP_NUMBER?.replace(/\D/g, '') || '';
  const phone = process.env.NEXT_PUBLIC_CONTACT_PHONE?.trim() || '';
  const phoneHref = phone.replace(/[^\d+]/g, '');
  const email = process.env.NEXT_PUBLIC_CONTACT_EMAIL?.trim() || '';

  const COLS = [
    {
      heading: t('footer.about') || 'About',
      links: [
        [t('footer.ourStory')    || 'Our Story',       '/airline/about'],
        [t('footer.about')       || 'About Us',        '/airline/about'],
        [t('footer.leadership')  || 'Leadership',      '/airline/about'],
        [t('footer.visionMission')|| 'Vision & Mission','/airline/about'],
        [t('footer.insights')    || 'Insights / Blog', '/airline/about'],
      ],
    },
    {
      heading: t('footer.services') || 'Services',
      links: [
        [t('footer.flightBooking') || 'Flight Booking', '/airline/book-flight'],
        [t('footer.charter')       || 'Charter',        '/airline/book-flight'],
        [t('footer.groupTravel')   || 'Group Travel',   '/airline/group-travel'],
        [t('footer.corporateTravel')|| 'Corporate',     '/airline/corporate-travel'],
        [t('footer.cargo')         || 'Cargo',          '/airline/cargo-services'],
        [t('footer.specialAssist') || 'Special Assist', '/airline/special-assistance'],
      ],
    },
    {
      heading: t('footer.support') || 'Support',
      links: [
        [t('footer.contactUs')    || 'Contact Us',      '/airline/contact'],
        [t('footer.faqs')         || 'FAQs',            '/airline/contact'],
        [t('footer.flightStatus') || 'Flight Status',   '/airline/flight-status'],
        [t('footer.manageBooking')|| 'Manage Booking',  '/airline/manage-booking'],
        [t('footer.grievance')    || 'Grievance',       '/grievance-redressal'],
        [t('footer.accessibility')|| 'Accessibility',   '/accessibility'],
      ],
    },
    {
      heading: t('footer.legalPolicies') || 'Legal & Policies',
      links: [
        [t('footer.privacy')             || 'Privacy Policy',           '/privacy-policy'],
        [t('footer.terms')               || 'Terms & Conditions',       '/terms-and-conditions'],
        [t('footer.cookies')             || 'Cookie Policy',            '/cookie-policy'],
        [t('footer.memberTerms')         || 'Membership Terms',         '/membership-terms'],
        [t('footer.cancellation')        || 'Cancellation & Refund',    '/cancellation-refund-policy'],
        [t('footer.franchiseDisclaimer') || 'Franchise Disclaimer',     '/franchise-disclaimer'],
        [t('footer.aviationDisclaimer')  || 'Aviation Disclaimer',      '/aviation-disclaimer'],
      ],
    },
  ];

  return (
    <footer style={{
      background: 'linear-gradient(180deg, #04036b 0%, #02024a 100%)',
      color: 'rgba(215,242,250,0.75)',
      paddingTop: 72,
      fontFamily: 'var(--al-body-font, Manrope, sans-serif)',
    }}>
      <div className="al-container">

        {/* ── Brand + contact strip ── */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: '1.6fr 1fr 1fr',
          gap: 48,
          paddingBottom: 48,
          borderBottom: '1px solid rgba(255,255,255,0.08)',
          marginBottom: 48,
        }}>
          {/* Brand block */}
          <div>
            <Link href="/airline" style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none', marginBottom: 20 }}>
              <span style={{
                width: 42, height: 42, borderRadius: '50%',
                background: '#ff4800',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontWeight: 800, fontSize: 17, color: '#fff', letterSpacing: -1,
              }}>SA</span>
              <span style={{ color: '#fff', fontSize: 14, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', lineHeight: 1.1 }}>
                SANATAN<br /><small style={{ fontSize: 9, fontWeight: 500, letterSpacing: '0.14em', opacity: 0.65 }}>AIRLINES</small>
              </span>
            </Link>

            {/* Traditional motif divider */}
            <div style={{ fontSize: 18, letterSpacing: 6, color: 'rgba(255,72,0,0.6)', marginBottom: 16 }}>
              ॐ ✦ ॐ ✦ ॐ
            </div>

            <p style={{ fontSize: 13.5, lineHeight: 1.75, color: 'rgba(215,242,250,0.65)', maxWidth: 300, marginBottom: 16 }}>
              {t('footer.tagline') || 'Connecting India and the world with warmth, reliability and world-class service.'}
            </p>

            {/* Seva | Satya | Vishwas */}
            <div style={{
              display: 'inline-block',
              fontSize: 12, fontWeight: 700, letterSpacing: '0.12em',
              color: 'rgba(255,72,0,0.9)',
              borderTop: '1px solid rgba(255,72,0,0.3)',
              paddingTop: 10, marginBottom: 20,
            }}>
              {t('footer.tagline2') || 'Seva | Satya | Vishwas'}
            </div>

            {/* Social icons */}
            <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
              {[
                { icon: <IconFacebook />,  label: 'Facebook',  href: '#' },
                { icon: <IconInstagram />, label: 'Instagram', href: '#' },
                { icon: <IconLinkedIn />,  label: 'LinkedIn',  href: '#' },
                { icon: <IconYoutube />,   label: 'YouTube',   href: '#' },
                ...(whatsappNumber ? [{ icon: <IconWhatsApp />, label: 'WhatsApp', href: `https://wa.me/${whatsappNumber}` }] : []),
              ].map(({ icon, label, href }) => (
                <a
                  key={label} href={href} aria-label={label}
                  target={href !== '#' ? '_blank' : undefined}
                  rel={href !== '#' ? 'noopener noreferrer' : undefined}
                  style={{
                    width: 36, height: 36, borderRadius: '50%',
                    background: 'rgba(255,255,255,0.08)',
                    border: '1px solid rgba(255,255,255,0.15)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    color: 'rgba(215,242,250,0.75)',
                    textDecoration: 'none',
                    transition: 'background 0.15s, color 0.15s',
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.background = 'rgba(255,72,0,0.3)'; e.currentTarget.style.color = '#fff'; }}
                  onMouseLeave={(e) => { e.currentTarget.style.background = 'rgba(255,255,255,0.08)'; e.currentTarget.style.color = 'rgba(215,242,250,0.75)'; }}
                >
                  {icon}
                </a>
              ))}
            </div>
          </div>

          {/* Contact block */}
          <div>
            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.35)', marginBottom: 20 }}>
              Contact
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <div style={{ display: 'flex', gap: 10, alignItems: 'flex-start' }}>
                <span style={{ fontSize: 16, flexShrink: 0, marginTop: 1 }}>📍</span>
                <span style={{ fontSize: 13, lineHeight: 1.65, color: 'rgba(215,242,250,0.65)' }}>
                  {t('footer.address') || 'Office No. 309, Elixa Park, Old Pune–Bangalore Highway, Shahupuri, Kolhapur, Maharashtra – 416001'}
                </span>
              </div>
              {phone && <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <span style={{ fontSize: 16, flexShrink: 0 }}>📞</span>
                <a href={`tel:${phoneHref}`} style={{ fontSize: 14, fontWeight: 700, color: 'rgba(215,242,250,0.9)', textDecoration: 'none' }}>
                  {phone}
                </a>
              </div>}
              {email && <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <span style={{ fontSize: 16, flexShrink: 0 }}>✉️</span>
                <a href={`mailto:${email}`} style={{ fontSize: 13, color: 'rgba(215,242,250,0.75)', textDecoration: 'none', wordBreak: 'break-all' }}>
                  {email}
                </a>
              </div>}
              {whatsappNumber && <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <span style={{ fontSize: 16, flexShrink: 0 }}>💬</span>
                <a href={`https://wa.me/${whatsappNumber}`} target="_blank" rel="noopener noreferrer" style={{ fontSize: 13, color: '#25D366', textDecoration: 'none', fontWeight: 600 }}>
                  WhatsApp
                </a>
              </div>}
            </div>
          </div>

          {/* Language switcher */}
          <div>
            <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.35)', marginBottom: 20 }}>
              {t('nav.language') || 'Language'}
            </div>
            <LanguageSwitcher />
            <p style={{ fontSize: 11.5, color: 'rgba(215,242,250,0.4)', marginTop: 12, lineHeight: 1.6 }}>
              Content available in 14 Indian languages. Select your preferred language above.
            </p>
          </div>
        </div>

        {/* ── Four-column link grid ── */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 1fr)',
          gap: 32,
          paddingBottom: 56,
          borderBottom: '1px solid rgba(255,255,255,0.08)',
        }}>
          {COLS.map((col) => (
            <div key={col.heading}>
              <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.35)', marginBottom: 18 }}>
                {col.heading}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                {col.links.map(([label, href]) => (
                  <Link
                    key={href + label}
                    href={href}
                    style={{ fontSize: 13.5, color: 'rgba(215,242,250,0.65)', textDecoration: 'none', padding: '5px 0', transition: 'color 0.15s' }}
                    onMouseEnter={(e) => { e.currentTarget.style.color = '#fff'; }}
                    onMouseLeave={(e) => { e.currentTarget.style.color = 'rgba(215,242,250,0.65)'; }}
                  >
                    {label}
                  </Link>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* ── Bottom bar ── */}
        <div style={{
          padding: '24px 0',
          display: 'flex', flexWrap: 'wrap',
          gap: 16, alignItems: 'center', justifyContent: 'space-between',
        }}>
          <div>
            <div style={{ fontSize: 12.5, color: 'rgba(255,255,255,0.35)' }}>
              © {year} Sanatan Airlines Pvt. Ltd. — {t('footer.legal') || 'Operated subject to DGCA and IATA regulations.'}
            </div>
          </div>
          <nav aria-label="Legal quick links" style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
            {[
              ['Privacy', '/privacy-policy'],
              ['Terms', '/terms-and-conditions'],
              ['Cookies', '/cookie-policy'],
              ['Grievance', '/grievance-redressal'],
              ['Accessibility', '/accessibility'],
            ].map(([label, href]) => (
              <Link key={href} href={href} style={{ fontSize: 12, color: 'rgba(255,255,255,0.35)', textDecoration: 'none' }}
                onMouseEnter={(e) => { e.currentTarget.style.color = 'rgba(255,255,255,0.7)'; }}
                onMouseLeave={(e) => { e.currentTarget.style.color = 'rgba(255,255,255,0.35)'; }}
              >
                {label}
              </Link>
            ))}
          </nav>
        </div>
      </div>

      {/* Responsive overrides */}
      <style>{`
        @media (max-width: 900px) {
          .al-footer-brand-grid { grid-template-columns: 1fr 1fr !important; }
          .al-footer-link-grid  { grid-template-columns: 1fr 1fr !important; }
        }
        @media (max-width: 540px) {
          .al-footer-brand-grid { grid-template-columns: 1fr !important; }
          .al-footer-link-grid  { grid-template-columns: 1fr !important; }
        }
      `}</style>
    </footer>
  );
}
